/**
 * Post-extract portfolio runtime patches (T0.1).
 *
 * Run after extract-portfolio-v25.mjs (or alone on the current runtime):
 *   node scripts/patch-portfolio-runtime.mjs
 *
 * Idempotent. Contains:
 *  - empty-collection / null-safety guards (from patch-portfolio-v25-empty-guards.mjs)
 *  - live lifecycle bridge (scripts/portfolio-runtime-live-bridge.inc.js)
 *  - capital-call / LP form + notices UI tweaks
 *  - IC vote data attrs, NaN guards, recipient harden helpers
 *
 * Hand-edited branches in lib/portfolio-v11-mock/nav.ts are NOT regenerated by
 * extract — keep them in source control; documented in the gap plan.
 */
import fs from "fs"
import path from "path"
import { fileURLToPath } from "url"
import { spawnSync } from "child_process"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.join(__dirname, "..")
const RUNTIME = path.join(ROOT, "components/portfolio-v11-mock/matanho-portfolio-runtime.js")
const BRIDGE = path.join(ROOT, "scripts/portfolio-runtime-live-bridge.inc.js")
const EMPTY_GUARDS = path.join(ROOT, "scripts/patch-portfolio-v25-empty-guards.mjs")

function must(cond, msg) {
  if (!cond) throw new Error(msg)
}

function replaceOnce(src, find, repl, label) {
  if (!src.includes(find)) {
    if (src.includes(repl) || (label && src.includes(`/* patched:${label} */`))) {
      console.log("skip (already)", label || find.slice(0, 48))
      return src
    }
    console.warn("MISS", label || find.slice(0, 80))
    return src
  }
  return src.replace(find, repl)
}

function replaceAllSafe(src, find, repl, label) {
  if (!src.includes(find)) {
    console.log("skip", label || find.slice(0, 48))
    return src
  }
  return src.replaceAll(find, repl)
}

// 1) Empty guards (existing script)
if (fs.existsSync(EMPTY_GUARDS)) {
  const r = spawnSync(process.execPath, [EMPTY_GUARDS], { cwd: ROOT, encoding: "utf8" })
  if (r.stdout) process.stdout.write(r.stdout)
  if (r.status !== 0) {
    console.warn("empty-guards exited", r.status, r.stderr)
  }
}

let s = fs.readFileSync(RUNTIME, "utf8")
